	"text() : \"\"; })\n  .then(function (name) {\n    deviceName = (name || \"\").trim().toUpperCase();\n    if"
	" (deviceName) { draw(); } // the title and the first crumb are its name\n  })\n  .catch(function () { "
	"/* the name is decoration; the page works without it */ });\n\nupdateHiddenButton();\nload(CARD);\n</scr"
	"ipt>\n</body>\n</html>\n";

#endif /* WEBPAGE_H */
